-- Canonical local demo inventory: 20 + 30 explicitly synthetic batch listings.
-- Static rows are self-contained. The ignored export and HDB training CSV are construction inputs only.
-- Synthetic flat model/storey/lease metadata was selected from 2017-01 through 2025-12 HDB transactions.
-- This metadata construction does not change model selection, training, calibration, or 2026 holdout evaluation.
-- Block and street were parsed once from the export and normalized to observed HDB training categories.
-- Canonical demo rows are not HDB-verified and must pass the local-only demo gate.
-- Complete explicit coordinates are preserved; town centroids are fallback-only.
DELETE FROM public.properties AS property
USING (VALUES
  ('Cozy 4-Room HDB in Tampines', 'Block 123 Tampines Street 11', 'Demo Seller'),
  ('Spacious 5-Room HDB in Woodlands', 'Block 456 Woodlands Drive 16', 'Demo Seller'),
  ('Charming 3-Room HDB in Bedok', 'Block 789 Bedok North Road', 'Demo Seller'),
  ('Cozy 3-Room Flat in Ang Mo Kio Central', 'Block 556 Ang Mo Kio Avenue 10', 'Demo Seller'),
  ('Spacious 4-Room with City View', 'Block 342 Ang Mo Kio Avenue 1', 'Demo Seller'),
  ('Modern Executive Apartment in Tampines', 'Block 823 Tampines Street 81', 'Demo Seller'),
  ('Affordable 2-Room Starter Home', 'Block 167 Woodlands Street 11', 'Demo Seller'),
  ('Waterfront 4-Room with Balcony', 'Block 268C Punggol Field', 'Demo Seller'),
  ('Renovated 3-Room near Bedok Mall', 'Block 123 Bedok North Street 2', 'Demo Seller')
) AS obsolete(title, detailed_location, seller_name)
WHERE property.title = obsolete.title
  AND property.detailed_location = obsolete.detailed_location
  AND property.seller_name = obsolete.seller_name;

